import{_ as a,o as d,c as e,ak as l}from"./chunks/framework.DKi5cyCJ.js";const m=JSON.parse('{"title":"嵌入式驱动面试手册","description":"CAN、I2C、SPI、UART、网络、定时器、PWM、启动链接、DMA、Cache 与中断","frontmatter":{"title":"嵌入式驱动面试手册","description":"CAN、I2C、SPI、UART、网络、定时器、PWM、启动链接、DMA、Cache 与中断","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-嵌入式驱动面试手册.md","filePath":"pages/blog/2026-10-20-嵌入式驱动面试手册.md"}'),r={name:"pages/blog/2026-10-20-嵌入式驱动面试手册.md"};function o(s,t,h,i,b,g){return d(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="嵌入式驱动面试手册" tabindex="-1">嵌入式驱动面试手册 <a class="header-anchor" href="#嵌入式驱动面试手册" aria-label="Permalink to &quot;嵌入式驱动面试手册&quot;">​</a></h1><blockquote><p>按总线和外设整理的面试笔记。寄存器例子默认 STM32F4 / APM32F4 这一类 Cortex-M，换芯片先对参考手册，不要照抄分频魔数。</p></blockquote><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">总线<br><small>CAN / I2C / SPI / UART</small></div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">时间<br><small>定时器 / PWM</small></div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">搬运<br><small>DMA / Cache</small></div><div class="blog-flow-arrow">→</div><div class="blog-flow-node accent">内核<br><small>中断 / 启动链接</small></div></div></div><h2 id="文章" tabindex="-1">文章 <a class="header-anchor" href="#文章" aria-label="Permalink to &quot;文章&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>先记住的一件事</th></tr></thead><tbody><tr><td><a href="/pages/blog/2026-10-20-CAN总线.html">CAN</a></td><td>一条干线、两端 120 Ω；ID 是优先级不是站地址</td></tr><tr><td><a href="/pages/blog/2026-10-20-I2C总线.html">I2C</a></td><td>开漏加上拉；SCL 为高时 SDA 下降是起始</td></tr><tr><td><a href="/pages/blog/2026-10-20-SPI总线.html">SPI</a></td><td>模式由 CPOL/CPHA 决定，片选期间不要抬高</td></tr><tr><td><a href="/pages/blog/2026-10-20-UART串口.html">UART</a></td><td>低位先发；发完看 TC，不要只看 TXE</td></tr><tr><td><a href="/pages/blog/2026-10-20-嵌入式网络TCP与UDP.html">网络</a></td><td>UDP 没有握手；TCP 是三次建立、四次关闭</td></tr><tr><td><a href="/pages/blog/2026-10-20-定时器.html">定时器</a></td><td>APB 分频不为 1 时，定时器时钟 ×2</td></tr><tr><td><a href="/pages/blog/2026-10-20-PWM.html">PWM</a></td><td>频率看 ARR，占空比看 CCR；TIM1 还要开 MOE</td></tr><tr><td><a href="/pages/blog/2026-10-20-内存启动与链接.html">内存与启动</a></td><td>复位后先拷 <code>.data</code>、清 <code>.bss</code>，再进 main</td></tr><tr><td><a href="/pages/blog/2026-10-20-DMA.html">DMA</a></td><td>NDTR 是数据个数；使能前先清标志</td></tr><tr><td><a href="/pages/blog/2026-10-20-Cache与DMA一致性.html">Cache</a></td><td>M4 没有 Cache；M7 发送要 Clean，接收要 Invalidate</td></tr><tr><td><a href="/pages/blog/2026-10-20-中断与抢占.html">中断</a></td><td>数值越小越优先；子优先级不能抢占</td></tr><tr><td><a href="/pages/blog/2026-10-21-手册前提与深水区.html">手册前提与深水区</a></td><td>哪些结论要加限定，以及看门狗、Modbus、低功耗</td></tr><tr><td><a href="/pages/blog/2026-10-21-中断优先级与FreeRTOS.html">中断优先级与 FreeRTOS</a></td><td>BASEPRI 分界；电流环不调 API</td></tr><tr><td><a href="/pages/blog/2026-10-21-ADC驱动.html">ADC</a></td><td>采样时间跟源阻抗走；ENOB 低于标称位数</td></tr><tr><td><a href="/pages/blog/2026-10-21-USB驱动.html">USB</a></td><td>主机轮询；CDC 波特率通常不是真实线速率</td></tr><tr><td><a href="/pages/blog/2026-10-21-RTOS线程与多轴.html">RTOS 线程与多轴</a></td><td>急停不进普通队列；五轴放在同一个运动任务</td></tr><tr><td><a href="/pages/blog/2026-10-21-插补与速度规划.html">插补与速度规划</a></td><td>路径插补 vs 单轴速度表；节拍≠短 Move；<a href="/demos/interp-demo.html" target="_blank">动态演示</a></td></tr></tbody></table><h2 id="动态演示" tabindex="-1">动态演示 <a class="header-anchor" href="#动态演示" aria-label="Permalink to &quot;动态演示&quot;">​</a></h2><p>各篇正文已内嵌动画；也可新窗口打开 <a href="/demos/index.html" target="_blank">演示索引</a>：CAN 时序/拓扑、I2C/SPI/UART/定时器/PWM 波形、TCP 握手、插补与前瞻。</p><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>IIC 与 I2C 是同一总线。</li><li>时序描述用逻辑电平：显性/低为 0，隐性/高为 1。示波器上的电压要对照收发器手册。</li><li>长度、上拉、采样点都依赖时钟和电缆。文中的数字写明了假设条件。</li></ul>',9)])])}const n=a(r,[["render",o]]);export{m as __pageData,n as default};
